import{_ as a,C as s,o as d,c as r,a5 as t,E as n}from"./chunks/framework.CslsFoWx.js";const f=JSON.parse(`{"title":"Équipe d'agents","description":"","frontmatter":{},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md","lastUpdated":1794619270000}`),l={name:"agents/index.md"};function i(u,e,c,p,g,m){const o=s("AgentFlow");return d(),r("div",null,[e[0]||(e[0]=t('<h1 id="equipe-d-agents" tabindex="-1">Équipe d&#39;agents <a class="header-anchor" href="#equipe-d-agents" aria-label="Permalink to &quot;Équipe d&#39;agents&quot;">​</a></h1><p>Vendora est développé par une équipe d&#39;agents IA spécialisés, orchestrée par un <strong>chef de lot</strong> (la session principale de Claude Code). Cette page montre comment ils travaillent ensemble et le déroulé d&#39;un lot, de la carte Trello au staging. Les <a href="/VendoraSystem-docs/agents/fiches">fiches des agents</a> détaillent chacun ; le <a href="/VendoraSystem-docs/agents/plan">plan</a> explique pourquoi cette organisation.</p><h2 id="les-regles-du-jeu" tabindex="-1">Les règles du jeu <a class="header-anchor" href="#les-regles-du-jeu" aria-label="Permalink to &quot;Les règles du jeu&quot;">​</a></h2><p><strong>Communication en étoile.</strong> Le chef de lot envoie un <em>brief</em> (fiche de lot, <code>CLAUDE.md</code> du module, format du rapport) et reçoit un <em>rapport</em> (branche, sortie réelle des tests, critère → test, restes). Il relance un agent avec <code>SendMessage</code>, l&#39;agent garde son contexte. <strong>Les agents ne se parlent jamais</strong> : ils lisent le dépôt (fiche <code>docs/lots/&lt;lot&gt;.md</code>, branches, diffs, captures). Seul le chef de lot fusionne dans <code>main</code> et écrit TRACKING, TODO, site, README et Trello.</p><p><strong>Garde-fous toujours actifs</strong> (<code>.claude/settings.json</code>, <code>.claude/hooks/</code>) :</p><table tabindex="0"><thead><tr><th>Moment</th><th>Garde-fou</th><th>Effet</th></tr></thead><tbody><tr><td>Démarrage de session</td><td>santé machine</td><td>processus (limite 2 666), zombies qemu, serveur sur 8080</td></tr><tr><td>Avant une commande</td><td><code>garde-bash.py</code></td><td>refuse <code>--rerun-tasks</code> pendant un bootRun, <code>./gradlew --stop</code>, <code>lsof -ti :8080</code></td></tr><tr><td>Avant une écriture (fichier, Trello)</td><td><code>garde-secrets.py</code></td><td>refuse clés, jetons, JWT, mots de passe</td></tr><tr><td>Fin de tour</td><td>rappel de fin de lot</td><td>rappelle <code>/lot-terminer</code> si du code change sans TRACKING</td></tr></tbody></table><p>Chaque refus est noté dans <code>.claude/hooks/refus.log</code> (motif seulement, ignoré par git) et relu par <code>/retro</code>.</p><h2 id="le-deroule-d-un-lot" tabindex="-1">Le déroulé d&#39;un lot <a class="header-anchor" href="#le-deroule-d-un-lot" aria-label="Permalink to &quot;Le déroulé d&#39;un lot&quot;">​</a></h2><p>Douze étapes dans l&#39;ordre. Les étapes 4 à 7 tournent en boucle jusqu&#39;à ce que les relecteurs disent OK ; un lot découpé en vagues les rejoue pour chaque vague.</p>',9)),n(o),e[1]||(e[1]=t('<h2 id="la-boucle-d-amelioration" tabindex="-1">La boucle d&#39;amélioration <a class="header-anchor" href="#la-boucle-d-amelioration" aria-label="Permalink to &quot;La boucle d&#39;amélioration&quot;">​</a></h2><p>Tous les 5 lots, <code>/retro</code> lit les mesures des fiches de lot, les <a href="/VendoraSystem-docs/agents/indicateurs">indicateurs</a>, les mémoires des agents, les cartes bug et le journal des refus, puis corrige <strong>un fichier</strong> (CLAUDE.md, skill, agent, hook ou évaluation) après validation d&#39;Ahmed. Les <a href="/VendoraSystem-docs/agents/evaluations">évaluations des agents</a> sont rejouées après chaque modification d&#39;un agent. Historique : <a href="/VendoraSystem-docs/agents/retros/2026-11-14">rétrospectives</a>.</p>',2))])}const _=a(l,[["render",i]]);export{f as __pageData,_ as default};
